{{ config(materialized='incremental') }}
/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_ACCOUNT_BALANCE
   anchor      : HUB_FINANCIAL_ACCOUNT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 1 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_FINANCIAL_ACCOUNT_HK
   hashdiff    : SAT_ACCOUNT_BALANCE_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_FINANCIAL_ACCOUNT|' || (HUB_FINANCIAL_ACCOUNT_BK__PLC_LOAN_ACC_NO))) as HUB_FINANCIAL_ACCOUNT_HK
        , PLC_SACTIONED_LOAN_AMT as OPENING_BALANCE
        , 'BA_HCP_PROD_8439_CLH_LOADER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_prod_8439_clh_loader') }}
    where (nullif(trim(PLC_LOAN_ACC_NO),'')) is not null
),

resolved as (
    select
        HUB_FINANCIAL_ACCOUNT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then OPENING_BALANCE end) as OPENING_BALANCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_FINANCIAL_ACCOUNT_HK
),

hashed as (
    select
        *,
        case when OPENING_BALANCE is not null
                     then md5(upper(coalesce(cast(OPENING_BALANCE as varchar), '')))
                end as SAT_ACCOUNT_BALANCE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_FINANCIAL_ACCOUNT_HK is not null
  and SAT_ACCOUNT_BALANCE_HASHDIFF is not null
